template:
@php
    $book = $show_contacts !== false && function_exists('contacts') ? contacts() : null;
    $book = $book !== null && ! $book->isEmpty() ? $book : null;
    $emails = $book?->emails() ?? [];
    $places = $book?->addresses() ?? [];
    $hours = $book !== null && $show_hours !== false && ! $book->hours()->isEmpty();
    $slug = is_string($form) ? trim($form) : '';
    // The form is the Inbox's tag, rendered only where the module is: a block type compiles
    // its template whole, and a tag of a package that is not installed would not compile.
    // The description is the line under the form's title in a dialog; here the headings of the
    // block say what the form is for, and the switch (off by default) brings the line back.
    $describe = $show_form_description === true;
    $inbox = $slug !== '' && class_exists(\WebxUi\Inbox\View\Components\Form::class)
        ? trim(\Illuminate\Support\Facades\Blade::render('<x-webx-inbox::form :slug="$slug" :description="$describe" />', ['slug' => $slug, 'describe' => $describe]))
        : '';
@endphp
@if ($heading || $book || $inbox !== '')
<section @class(['b-contact', 'b-contact--both' => $book && $inbox !== '']) data-wx-block="contact">
    @if ($heading || $text)
        <div class="b-contact__head">
            @if ($heading)
                <h2 class="b-contact__heading">{{ $heading }}</h2>
            @endif
            @if ($text)
                <p class="b-contact__text">{{ $text }}</p>
            @endif
        </div>
    @endif
    <div class="b-contact__grid">
        @if ($book)
            <div class="b-contact__details">
                @if ($book->phones() !== [])
                    <div class="b-contact__item">
                        <h3 class="b-contact__label"><x-theme::icon name="phone" class="b-contact__icon" />{{ __('theme::theme.blocks.contact.phone') }}</h3>
                        <x-webx-phones layout="list" class="b-contact__phones" />
                    </div>
                @endif
                @if ($emails !== [])
                    <div class="b-contact__item">
                        <h3 class="b-contact__label"><x-theme::icon name="mail" class="b-contact__icon" />{{ __('theme::theme.blocks.contact.email') }}</h3>
                        @foreach ($emails as $email)
                            <a class="b-contact__link" href="{{ $email->href() }}">{{ $email->address }}</a>
                        @endforeach
                    </div>
                @endif
                @if ($places !== [])
                    <div class="b-contact__item">
                        <h3 class="b-contact__label"><x-theme::icon name="map-pin" class="b-contact__icon" />{{ __('theme::theme.blocks.contact.address') }}</h3>
                        @foreach ($places as $place)
                            <address class="b-contact__address">
                                @if ($place->mapUrl() !== null)
                                    <a class="b-contact__link" href="{{ $place->mapUrl() }}" target="_blank" rel="noopener">{{ $place->text }}</a>
                                @else
                                    {{ $place->text }}
                                @endif
                            </address>
                        @endforeach
                    </div>
                @endif
                @if ($hours)
                    {{-- The table names itself: it has a heading of its own. --}}
                    <div class="b-contact__item">
                        <x-webx-hours layout="table" class="b-contact__hours" />
                    </div>
                @endif
                @if ($book->socials() !== [])
                    <div class="b-contact__item">
                        <h3 class="b-contact__label"><x-theme::icon name="share" class="b-contact__icon" />{{ __('theme::theme.blocks.contact.socials') }}</h3>
                        <x-webx-socials class="b-contact__socials" />
                    </div>
                @endif
            </div>
        @endif
        @if ($inbox !== '')
            <div class="b-contact__form">
                @if ($form_heading)
                    <h3 class="b-contact__form-heading">{{ $form_heading }}</h3>
                @endif
                {!! $inbox !!}
            </div>
        @endif
    </div>
</section>
@endif

styles:
.b-contact {
    container-type: inline-size;
    padding-block: var(--site-space-6);
}

.b-contact__head {
    max-width: 42rem;
    margin-bottom: var(--site-space-5);
}

.b-contact__heading {
    margin: 0 0 var(--site-space-2);
}

.b-contact__text {
    margin: 0;
    color: var(--site-color-text-muted);
}

.b-contact__grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--site-space-6);
}

.b-contact__details {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-content: start;
    gap: var(--site-space-5);
}

.b-contact__item {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--site-space-1);
    min-width: 0;
}

.b-contact__label {
    display: flex;
    align-items: center;
    gap: var(--site-space-2);
    margin: 0 0 var(--site-space-1);
    color: var(--site-color-text-muted);
    font-family: var(--site-font-body);
    font-size: var(--site-font-size-6);
    font-weight: 600;
    letter-spacing: 0.02em;
}

.b-contact__icon {
    color: var(--site-color-accent);
}

.b-contact__link {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
    overflow-wrap: anywhere;
}

.b-contact__address {
    font-style: normal;
}

.b-contact__form {
    min-width: 0;
    padding: var(--site-space-5);
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-lg);
    background: var(--site-color-surface);
    color: var(--site-color-text);
}

.b-contact__form-heading {
    margin: 0 0 var(--site-space-4);
    font-size: var(--site-font-size-4);
}

@container (min-width: 36rem) {
    .b-contact__details {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@container (min-width: 56rem) {
    .b-contact--both .b-contact__grid {
        grid-template-columns: minmax(0, 2fr) minmax(0, 3fr);
        align-items: start;
    }

    .b-contact--both .b-contact__details {
        grid-template-columns: minmax(0, 1fr);
    }
}
